public class Camera : MonoBehaviour
{
    public Vector3 cameraPosition;
    public Vector3 cameraDirection;

    private Vector3 _cameraPosition;
    private Vector3 _cameraDirection;

    void Start()
    {
        _cameraPosition = Camera.main.ScreenToWorldPoint(_cameraPosition);
        _cameraDirection = Camera.main.ScreenToWorldPoint(_cameraDirection);
    }

    public void Update()
    {
        Vector3 cameraPosition = Camera.main.ScreenToWorldPoint(_cameraPosition);
        Vector3 cameraDirection = Camera.main.ScreenToWorldPoint(_cameraDirection);

        Vector3 newPosition = cameraPosition - cameraDirection;
        newPosition = newPosition.normalized;

        Camera.main.ScreenToWorldPoint(_cameraPosition);
        Camera.main.ScreenToWorldPoint(_cameraDirection);
    }
}


