        super("Straight flush", 10, 10);
    }

    static test(cards) {
        const counts = {};

        for (let card of cards) {
            counts[card.suit] = (counts[card.suit] || []).concat(card);
        }

        const flusharr = Object.keys(counts[0]).filter((key) => {
            return key === 10;
        });

        if (flusharr.length === 1) {
            return null;
        }

        let sorted_rank = [];

        for (let card of cards) {
            sorted_rank.push(card.rank);
        }

        const flushCards = counts.filter((card) => {
            return card.rank === sorted_rank[0];
        });

        if (flushCards.length === 1) {
            return flushCards;
        }

        let remainingCards = [];

        for (let i = 0; i < flushcards.length; i++) {
            if (sorted_rank.indexOf(flushcards[i].rank) !== -1) {
                remainingCards.push(flushcards[i]);
            }
        }

        let output = {
            combination: this,
            cards: flushcards.slice(0, 5),
        };

        return output;
    }
}

